        const lstStyle = getElementByLocalName(txBody, "lstStyle");
        const lvlPr = lstStyle ? getElementByLocalName(lstStyle, `lvl${Math.min(9, lvl + 1)}pPr`) : null;
        if (!lvlPr) return null;

        const fromLvl = lvlPr.getAttribute(attrName);
