                    id: `shape_${slideNum}_${opts.tag}imgfill${opts.nextId()}`,
                    kind: "imagefill",
                    ...base,
                    src: imageSrc,
                    fillMode: blipFillInfo.mode,
                    tileSizeX: blipFillInfo.tileSizeX,
                    tileSizeY: blipFillInfo.tileSizeY,
                    tileAlign: blipFillInfo.tileAlign,
                    srcRect: blipFillInfo.srcRect,
                    paragraphs: [],
