        // css/slide-editor.css. (These also used to be sized w-10 here but
        // w-9 in the markup, so every toggle silently resized the button.)
        const snapBtn = document.getElementById("btn-snap-toggle");
        const gridBtn = document.getElementById("btn-grid-toggle");
        if (snapBtn) snapBtn.classList.toggle("is-active", !!state.snapEnabled);
