            bezierEl.points = absPoints.map((node) => ({
                x: node.x - minX,
                y: node.y - minY,
                h1x: node.h1x - minX,
                h1y: node.h1y - minY,
                h2x: node.h2x - minX,
                h2y: node.h2y - minY,
            }));

            bezierEl.x = Math.round((minX / 1280) * 100);
            bezierEl.y = Math.round((minY / 720) * 100);
            bezierEl.w = Math.round((width / 1280) * 100);
            bezierEl.h = Math.round((height / 720) * 100);
