/* End src/renderer/panel/features/slide-editor/edit/tools.js */


/* Begin src/renderer/panel/features/slide-editor/edit/transform.js */

/* =========================================================================
   BSPSlideEditor — transform HUD, border radius & background color tools
   -------------------------------------------------------------------------
   The selection transform overlay (corner resize handles, with circle-aware
   resizing), border-radius controls (locked-all vs per-corner), pencil
   loop-fill toggle, and the slide background color utilities (hex sync, copy,
   paste, eyedropper).

   Depends on edit/geometry.js (normalizeCircleGeometry), edit/builder.js
   (syncBuilderStyleInspector, updateSlideBackground — same edit namespace),
   render and app. State in BSPSlideEditor.state.
   ========================================================================= */
(function (BSPSlideEditor) {
    "use strict";

    const edit = BSPSlideEditor.edit = BSPSlideEditor.edit || {};
    const state = BSPSlideEditor.state;
    const render = BSPSlideEditor.render = BSPSlideEditor.render || {};
    const app = BSPSlideEditor.app = BSPSlideEditor.app || {};

    function attachTransformControlsHUD() {
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === state.selectedElementId);
        if (!el) return;

        const board = document.getElementById("slide-canvas");
        if (!board) return;

        board.querySelectorAll(".transform-border").forEach((node) => node.remove());

        const wrapper = document.createElement("div");
        wrapper.className = "transform-border";
        wrapper.style.left = `${el.x}%`;
        wrapper.style.top = `${el.y}%`;
        wrapper.style.width = `${el.w}%`;
        wrapper.style.height = `${el.h}%`;

        // 8 handles: 4 corners + 4 edge midpoints (PowerPoint-style).
        const handles = [
            { name: "tl", style: "top: -20px; left: -20px; cursor: nwse-resize;" },
            { name: "tr", style: "top: -20px; right: -20px; cursor: nesw-resize;" },
            { name: "bl", style: "bottom: -20px; left: -20px; cursor: nesw-resize;" },
            { name: "br", style: "bottom: -20px; right: -20px; cursor: nwse-resize;" },
            { name: "t", style: "top: -20px; left: 50%; transform: translateX(-50%); cursor: ns-resize;" },
            { name: "b", style: "bottom: -20px; left: 50%; transform: translateX(-50%); cursor: ns-resize;" },
            { name: "l", style: "top: 50%; left: -20px; transform: translateY(-50%); cursor: ew-resize;" },
            { name: "r", style: "top: 50%; right: -20px; transform: translateY(-50%); cursor: ew-resize;" },
        ];

        handles.forEach((h) => {
            const handleDiv = document.createElement("div");
            handleDiv.className = "transform-handle";
            handleDiv.style = h.style;

            handleDiv.addEventListener("mousedown", (e) => {
                e.stopPropagation();
                e.preventDefault();
                startResizeTransform(e, h.name, el);
            });

            wrapper.appendChild(handleDiv);
        });

        board.appendChild(wrapper);
    }

    function startResizeTransform(e, handle, el) {
        const startX = e.clientX;
        const startY = e.clientY;

        const origX = el.x;
        const origY = el.y;
        const origW = el.w;
        const origH = el.h;

        function onResizeDrag(moveEv) {
            const dx = (moveEv.clientX - startX) / state.scale;
            const dy = (moveEv.clientY - startY) / state.scale;

            const dxPercent = (dx / 1280) * 100;
            const dyPercent = (dy / 720) * 100;

            if (el.type === "shape" && el.shapeType === "CIRCLE") {
                const origDiameterPx = Math.min((origW / 100) * 1280, (origH / 100) * 720);
                const signedDx = handle.includes("l") ? -dx : dx;
                const signedDy = handle.includes("t") ? -dy : dy;
                let diameterPx = Math.max(4, origDiameterPx + Math.max(signedDx, signedDy));
                const newW = Number(((diameterPx / 1280) * 100).toFixed(3));
                const newH = Number(((diameterPx / 720) * 100).toFixed(3));

                if (handle.includes("l")) {
                    el.x = Math.max(0, origX + origW - newW);
                }
                if (handle.includes("t")) {
                    el.y = Math.max(0, origY + origH - newH);
                }
                if (!handle.includes("l")) {
                    el.x = origX;
                }
                if (!handle.includes("t")) {
                    el.y = origY;
                }

                el.w = newW;
                el.h = newH;
                edit.normalizeCircleGeometry(el, "width");
                render.renderActiveSlideOnCanvas();
                return;
            }

            // Unified edge math for all 8 handles. Each handle moves the edges
            // named in it (l/r/t/b); corners move two, midpoints move one.
            const movesL = handle.includes("l");
            const movesR = handle.includes("r");
            const movesT = handle.includes("t");
            const movesB = handle.includes("b");

            let nx = origX, ny = origY, nw = origW, nh = origH;
            if (movesR) nw = Math.min(Math.max(origW + dxPercent, 0.5), 100 - origX);
            if (movesL) {
                const newX = Math.min(Math.max(origX + dxPercent, 0), origX + origW - 0.5);
                nx = newX;
                nw = origW - (newX - origX);
            }
            if (movesB) nh = Math.min(Math.max(origH + dyPercent, 0.5), 100 - origY);
            if (movesT) {
                const newY = Math.min(Math.max(origY + dyPercent, 0), origY + origH - 0.5);
                ny = newY;
                nh = origH - (newY - origY);
            }
            el.x = Math.round(nx);
            el.y = Math.round(ny);
            el.w = Math.round(nw);
            el.h = Math.round(nh);

            // Snap the dragged edges to slide center/edges and sibling elements.
            const snapped = edit.snapResizeEdges(el, handle, { x: el.x, y: el.y, w: el.w, h: el.h });
            el.x = snapped.g.x;
            el.y = snapped.g.y;
            el.w = snapped.g.w;
            el.h = snapped.g.h;
            edit.drawSnapGuides(snapped.guides);

            render.renderActiveSlideOnCanvas();
        }

        function onResizeRelease() {
            document.removeEventListener("mousemove", onResizeDrag);
            document.removeEventListener("mouseup", onResizeRelease);
            edit.clearSnapGuides();
        }

        document.addEventListener("mousemove", onResizeDrag);
        document.addEventListener("mouseup", onResizeRelease);
    }

    function toggleRadiusLock() {
        state.isRadiusLocked = !state.isRadiusLocked;
        const lockBtn = document.getElementById("btn-radius-lock");
        const lockSvg = document.getElementById("svg-radius-lock");
        const collectiveBlock = document.getElementById("collective-radius-block");
        const individualBlock = document.getElementById("individual-radius-block");

        if (lockBtn) {
            lockBtn.classList.toggle("is-active", state.isRadiusLocked);
            lockBtn.title = state.isRadiusLocked ? "Unlock Corners" : "Lock Corners Together";
        }
        if (lockSvg) {
            lockSvg.innerHTML = state.isRadiusLocked
                ? '<rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/>'
                : '<rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V8a5 5 0 0 1 9.9-1"/>';
        }
        if (collectiveBlock && individualBlock) {
            collectiveBlock.classList.toggle("hidden", !state.isRadiusLocked);
            individualBlock.classList.toggle("hidden", state.isRadiusLocked);
        }

        edit.syncBuilderStyleInspector();
    }

    function updateBorderRadiusAll(value) {
        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide?.elements.find((item) => item.id === state.selectedElementId);
        if (!el || (el.type !== "shape" && el.type !== "image")) return;

        const radius = Math.max(0, parseInt(value, 10) || 0);
        el.rtl = radius;
        el.rtr = radius;
        el.rbr = radius;
        el.rbl = radius;

        document.getElementById("lbl-radius-all").textContent = `${radius}px`;
        document.getElementById("inp-radius-tl").value = radius;
        document.getElementById("inp-radius-tr").value = radius;
        document.getElementById("inp-radius-br").value = radius;
        document.getElementById("inp-radius-bl").value = radius;

        render.renderActiveSlideOnCanvas();
    }

    function updateBorderRadiusIndividual(corner, value) {
        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide?.elements.find((item) => item.id === state.selectedElementId);
        if (!el || (el.type !== "shape" && el.type !== "image")) return;

        const radius = Math.max(0, parseInt(value, 10) || 0);
        el[corner] = radius;

        if (state.isRadiusLocked) {
            updateBorderRadiusAll(radius);
            return;
        }

        render.renderActiveSlideOnCanvas();
    }

    function togglePencilLoopFill(isFilled) {
        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === state.selectedElementId);
        if (el && (el.type === "pencil" || el.type === "bezier")) {
            el.isLoopFilled = isFilled;
            if (isFilled && !el.fillColor) el.fillColor = "#22d3ee";
            if (isFilled && el.fillOpacity == null) el.fillOpacity = 1;
            render.renderActiveSlideOnCanvas();
            edit.syncBuilderStyleInspector();
            app.createToast(isFilled ? "Fill enabled" : "Fill removed", "info");
        }
    }

    function syncBgColorText(hexVal) {
        if (/^#[0-9A-F]{6}$/i.test(hexVal)) {
            edit.updateSlideBackground(hexVal);
        }
    }

    function copyBackgroundHex() {
        const currentSlide = state.slides[state.activeSlideIndex];
        const hex = currentSlide.background || "#0B0F19";

        const tempInp = document.createElement("input");
        tempInp.value = hex;
        document.body.appendChild(tempInp);
        tempInp.select();
        document.execCommand("copy");
        document.body.removeChild(tempInp);

        app.createToast(`Copied Hex code ${hex} to Clipboard!`, "success");
    }

    async function pasteBackgroundHex() {
        try {
            const text = await navigator.clipboard.readText();
            if (/^#[0-9A-F]{6}$/i.test(text.trim())) {
                edit.updateSlideBackground(text.trim());
                app.createToast(`Pasted background style ${text.trim()}`, "success");
            } else {
                app.createToast("Invalid Hex code inside clipboard.", "error");
            }
        } catch (err) {
            const pasted = prompt("Paste your slide HEX color value below:", "#");
            if (pasted && /^#[0-9A-F]{6}$/i.test(pasted.trim())) {
                edit.updateSlideBackground(pasted.trim());
            }
        }
    }

    async function triggerCanvasEyedropper() {
        if (!window.EyeDropper) {
            app.createToast("Native EyeDropper not supported in this browser. Please type Hex value manually.", "error");
            return;
        }

        try {
            const eyeDropper = new EyeDropper();
            const result = await eyeDropper.open();
            edit.updateSlideBackground(result.sRGBHex);
            app.createToast(`Sampled color ${result.sRGBHex} from Screen!`, "success");
        } catch (e) {
            // User cancelled color dropper
        }
    }

    Object.assign(edit, {
        attachTransformControlsHUD,
        startResizeTransform,
        toggleRadiusLock,
        updateBorderRadiusAll,
        updateBorderRadiusIndividual,
        togglePencilLoopFill,
        syncBgColorText,
        copyBackgroundHex,
        pasteBackgroundHex,
        triggerCanvasEyedropper,
    });
})(window.BSPSlideEditor = window.BSPSlideEditor || {});

/* End src/renderer/panel/features/slide-editor/edit/transform.js */


/* Begin src/renderer/panel/features/slide-editor/edit/modifier-shapes.js */

/* =========================================================================
   BSPSlideEditor — Modifier-mode shape editing (select / move / resize / restyle)
   -------------------------------------------------------------------------
   Makes imported PPTX vector shapes editable on the canvas with PowerPoint
   semantics:
     - Only slide-sourced shapes are selectable; layout/master decorations
       stay locked, exactly like PowerPoint.
     - Clicking any shape inside a group selects the whole top-level group
       (PowerPoint's first click), which moves/resizes as one unit.
     - On a text shape, the first click selects the box; clicking again
       inside the selected box places the caret for text editing.
   Every committed edit is written back into the slide's XML document
   (<a:xfrm> off/ext, <a:solidFill>, <a:ln>), so Save/Export round-trips the
   changes into the .pptx.

   Depends on state (pptxSlideSizeEmu, modifierSlides), render
   (renderActiveSlideOnCanvas). Renderer calls attachModifierShapeInteractions
   per shape div and attachModifierSelectionHUD after the shape loop.
   ========================================================================= */
(function (BSPSlideEditor) {
  'use strict';

  const edit = (BSPSlideEditor.edit = BSPSlideEditor.edit || {});
  const state = BSPSlideEditor.state;
  const render = (BSPSlideEditor.render = BSPSlideEditor.render || {});
  const app = (BSPSlideEditor.app = BSPSlideEditor.app || {});

  const A_NS = 'http://schemas.openxmlformats.org/drawingml/2006/main';
  const FILL_KINDS = { shape: true, text: true };
  const STROKE_KINDS = { shape: true, text: true, connector: true, imagefill: true };

  let hudWrapper = null; // live HUD node (kept during drags, styles updated)
  let installed = false;

  const byLocal = (parent, name) => {
    if (!parent) return null;
    for (let i = 0; i < parent.childNodes.length; i++) {
      const c = parent.childNodes[i];
      if (c && c.nodeType === 1 && c.localName === name) return c;
    }
    return null;
  };

  const boardWpx = () => 1280;
  const boardHpx = () => {
    const emu = state.pptxSlideSizeEmu;
    return emu && emu.cx > 0 && emu.cy > 0 ? Math.round(1280 * (emu.cy / emu.cx)) : 720;
  };

  const currentSlide = () => state.slides[state.activeSlideIndex];

  /* ---- selection ------------------------------------------------------ */

  function selectionMembers() {
    const sel = state.pptxSelection;
    const slide = currentSlide();
    if (!sel || !slide || !slide.shapes) return [];
    return slide.shapes.filter((s) => sel.ids.includes(s.id));
  }

  function selectionBBox(members) {
    let l = Infinity,
      t = Infinity,
      r = -Infinity,
      b = -Infinity;
    members.forEach((s) => {
      l = Math.min(l, s.left);
      t = Math.min(t, s.top);
      r = Math.max(r, s.left + s.width);
      b = Math.max(b, s.top + s.height);
    });
    return { x: l, y: t, w: Math.max(0.01, r - l), h: Math.max(0.01, b - t) };
  }

  // Normal (first) click selects the whole top-level group. `drillIn` (a
  // double-click) enters the group and selects just this one child, so its
  // fill/stroke/geometry can be edited individually — PowerPoint semantics.
  function selectModifierShape(shape, drillIn) {
    const slide = currentSlide();
    if (!shape.editable || !slide) return;
    // Selecting anything other than the shape under point-edit leaves that mode.
    if (state.nodeEditShapeId && state.nodeEditShapeId !== shape.id) {
      state.nodeEditShapeId = null;
      state.nodeEditModel = null;
    }
    const asGroup = shape.groupId && !drillIn;
    const ids = asGroup
      ? slide.shapes.filter((s) => s.groupId === shape.groupId).map((s) => s.id)
      : [shape.id];
    state.pptxSelection = {
      ids,
      groupId: asGroup ? shape.groupId : null,
      groupNode: asGroup ? shape.groupNode || null : null,
    };
    render.renderActiveSlideOnCanvas();
  }

  function clearModifierSelection(rerender = true) {
    if (!state.pptxSelection) return;
    state.pptxSelection = null;
    if (rerender) render.renderActiveSlideOnCanvas();
  }

  // The set of shape ids that form one selection "unit" for the shape the
  // user clicked: the whole group if it belongs to one, else just itself.
  function unitIdsFor(shape) {
    const slide = currentSlide();
    if (shape.groupId && slide)
      return slide.shapes.filter((s) => s.groupId === shape.groupId).map((s) => s.id);
    return [shape.id];
  }

  // Shift-click: add/remove this shape's unit from the current selection.
  function toggleSelectShape(shape) {
    if (!shape.editable) return;
    const unit = unitIdsFor(shape);
    const cur = (state.pptxSelection && state.pptxSelection.ids) || [];
    const already = unit.every((id) => cur.includes(id));
    const ids = already ? cur.filter((id) => !unit.includes(id)) : [...new Set([...cur, ...unit])];
    state.pptxSelection = ids.length ? { ids, groupId: null, groupNode: null } : null;
    render.renderActiveSlideOnCanvas();
  }

  function selectByIds(ids) {
    state.pptxSelection = ids.length
      ? { ids: [...new Set(ids)], groupId: null, groupNode: null }
      : null;
    render.renderActiveSlideOnCanvas();
  }

  let recordsGroupSeq = 0;

  // Group the current multi-selection into one editing unit (records-level:
  // a shared groupId, no XML restructuring — export stays byte-faithful, and
  // it is fully reversible). Moves then act on all members together.
  function groupSelection() {
    const members = selectionMembers();
    if (members.length < 2) return;
    const gid = `bspgrp_${Date.now()}_${++recordsGroupSeq}`;
    members.forEach((s) => {
      s.groupId = gid;
      s.groupNode = null;
    });
    state.pptxSelection = { ids: members.map((s) => s.id), groupId: gid, groupNode: null };
    render.renderActiveSlideOnCanvas();
    app.createToast && app.createToast(`Grouped ${members.length} shapes.`, 'info');
  }

  // Ungroup: drop the shared groupId so each piece becomes independently
  // selectable/movable/re-colorable (PowerPoint's Ungroup, for editing).
  function ungroupSelection() {
    const sel = state.pptxSelection;
    const slide = currentSlide();
    if (!sel || !slide) return;
    const gids = new Set(
      selectionMembers()
        .map((s) => s.groupId)
        .filter(Boolean),
    );
    if (!gids.size) return;
    let n = 0;
    slide.shapes.forEach((s) => {
      if (gids.has(s.groupId)) {
        s.groupId = null;
        s.groupNode = null;
        n++;
      }
    });
    render.renderActiveSlideOnCanvas();
    app.createToast &&
      app.createToast(`Ungrouped ${n} shapes — click any piece to edit it.`, 'info');
  }

  function selectionHasGroup() {
    return selectionMembers().some((s) => s.groupId);
  }

  /* ---- z-order (records paint order + XML sibling order) ----------------- */

  const SHAPE_TAGS = { sp: 1, pic: 1, graphicFrame: 1, cxnSp: 1, grpSp: 1 };

  function moveNodeToEnd(node) {
    const p = node.parentNode;
    if (p) p.appendChild(node);
  }
  function moveNodeToFront(node) {
    const p = node.parentNode;
    if (!p) return;
    let first = null;
    for (let i = 0; i < p.childNodes.length; i++) {
      const c = p.childNodes[i];
      if (c.nodeType === 1 && SHAPE_TAGS[c.localName]) {
        first = c;
        break;
      }
    }
    if (first && first !== node) p.insertBefore(node, first);
  }

  function reorderSelection(toFront) {
    const sel = state.pptxSelection;
    const slide = currentSlide();
    if (!sel || !slide) return;
    const idset = new Set(sel.ids);
    const picked = slide.shapes.filter((s) => idset.has(s.id));
    const rest = slide.shapes.filter((s) => !idset.has(s.id));
    slide.shapes = toFront ? [...rest, ...picked] : [...picked, ...rest];
    // Mirror in XML so export keeps the same stacking.
    (toFront ? picked : [...picked].reverse()).forEach((s) => {
      if (s.srcNode) (toFront ? moveNodeToEnd : moveNodeToFront)(s.srcNode);
    });
    render.renderActiveSlideOnCanvas();
    app.createToast && app.createToast(toFront ? 'Brought to front.' : 'Sent to back.', 'info');
  }

  /* ---- text color ------------------------------------------------------- */

  function writeRunColor(tNode, hex) {
    const doc = slideDoc();
    const rNode = tNode ? tNode.parentNode : null;
    if (!rNode || !doc) return;
    let rPr = byLocal(rNode, 'rPr');
    if (!rPr) {
      rPr = doc.createElementNS(A_NS, 'a:rPr');
      rNode.insertBefore(rPr, rNode.firstChild); // rPr precedes <a:t>
    }
    ['noFill', 'solidFill', 'gradFill', 'pattFill'].forEach((t) => {
      const n = byLocal(rPr, t);
      if (n) rPr.removeChild(n);
    });
    const fill = doc.createElementNS(A_NS, 'a:solidFill');
    const clr = doc.createElementNS(A_NS, 'a:srgbClr');
    clr.setAttribute('val', hex.replace('#', '').toUpperCase());
    fill.appendChild(clr);
    // solidFill follows <a:ln> if present, else leads.
    const ln = byLocal(rPr, 'ln');
    rPr.insertBefore(fill, ln ? ln.nextSibling : rPr.firstChild);
  }

  function setSelectionTextColor(hex) {
    selectionMembers().forEach((s) => {
      if (s.kind !== 'text' || !s.paragraphs) return;
      s.paragraphs.forEach((p) =>
        p.forEach((run) => {
          run.color = hex;
          if (run.nodeRef) writeRunColor(run.nodeRef, hex);
        }),
      );
    });
    render.renderActiveSlideOnCanvas();
  }

  /* ---- XML write-back -------------------------------------------------- */

  function slideDoc() {
    const slide = currentSlide();
    return slide ? slide.xmlDoc : null;
  }

  // spPr for sp/pic/cxnSp; the graphicFrame's transform lives directly on
  // the frame as <p:xfrm>.
  function xfrmContainerFor(node) {
    if (!node) return null;
    if (node.localName === 'graphicFrame') return node;
    if (node.localName === 'grpSp') return byLocal(node, 'grpSpPr');
    return byLocal(node, 'spPr');
  }

  function ensureXfrm(node, seedPct) {
    const holder = xfrmContainerFor(node);
    if (!holder) return null;
    let xfrm = byLocal(holder, 'xfrm');
    const doc = slideDoc();
    if (!xfrm && doc) {
      xfrm = doc.createElementNS(A_NS, 'a:xfrm');
      holder.insertBefore(xfrm, holder.firstChild); // schema: xfrm first
    }
    if (!xfrm) return null;
    let off = byLocal(xfrm, 'off');
    let ext = byLocal(xfrm, 'ext');
    if (!off && doc) {
      off = doc.createElementNS(A_NS, 'a:off');
      xfrm.insertBefore(off, xfrm.firstChild);
    }
    if (!ext && doc) {
      ext = doc.createElementNS(A_NS, 'a:ext');
      xfrm.insertBefore(ext, off ? off.nextSibling : null);
    }
    if (!off || !ext) return null;
    // A shape inheriting placeholder geometry has a fresh empty xfrm:
    // seed it with the record's current absolute geometry.
    if (seedPct && !off.getAttribute('x')) {
      const emu = state.pptxSlideSizeEmu;
      off.setAttribute('x', `${Math.round((seedPct.left / 100) * emu.cx)}`);
      off.setAttribute('y', `${Math.round((seedPct.top / 100) * emu.cy)}`);
      ext.setAttribute('cx', `${Math.round((seedPct.width / 100) * emu.cx)}`);
      ext.setAttribute('cy', `${Math.round((seedPct.height / 100) * emu.cy)}`);
    }
    return { xfrm, off, ext };
  }

  // Affine map from the drag-start bbox to the current bbox, applied in EMU.
  function mapXfrmThroughBBox(nodes, origBB, newBB) {
    const emu = state.pptxSlideSizeEmu;
    const kx = newBB.w / origBB.w;
    const ky = newBB.h / origBB.h;
    const origXEmu = (origBB.x / 100) * emu.cx;
    const origYEmu = (origBB.y / 100) * emu.cy;
    const newXEmu = (newBB.x / 100) * emu.cx;
    const newYEmu = (newBB.y / 100) * emu.cy;

    nodes.forEach(({ off, ext }) => {
      const x = parseInt(off.getAttribute('x') || '0', 10);
      const y = parseInt(off.getAttribute('y') || '0', 10);
      const cx = parseInt(ext.getAttribute('cx') || '0', 10);
      const cy = parseInt(ext.getAttribute('cy') || '0', 10);
      off.setAttribute('x', `${Math.round(newXEmu + (x - origXEmu) * kx)}`);
      off.setAttribute('y', `${Math.round(newYEmu + (y - origYEmu) * ky)}`);
      ext.setAttribute('cx', `${Math.round(cx * kx)}`);
      ext.setAttribute('cy', `${Math.round(cy * ky)}`);
    });
  }

  // Cumulative affine (EMU) that maps a shape node's OWN local coordinate
  // space to absolute slide space, composed through every ancestor <p:grpSp>.
  // Each group maps child→parent as parent = child*scale + (off - chOff*scale),
  // so abs = local*S + T with S = ∏ scales and T composed outward. Inverting
  // it lets us write a shape's own <a:off>/<a:ext> from its absolute geometry
  // even when it lives inside one or more groups (rotation not composed).
  function ancestorAffineEmu(node) {
    let sx = 1,
      sy = 1,
      tx = 0,
      ty = 0;
    let cursor = node;
    while (cursor && cursor.parentNode) {
      const parent = cursor.parentNode;
      if (parent.localName === 'grpSp') {
        const gx = byLocal(byLocal(parent, 'grpSpPr'), 'xfrm');
        const off = byLocal(gx, 'off'),
          ext = byLocal(gx, 'ext');
        const chOff = byLocal(gx, 'chOff'),
          chExt = byLocal(gx, 'chExt');
        if (off && ext && chOff && chExt) {
          const ox = +off.getAttribute('x'),
            oy = +off.getAttribute('y');
          const ecx = +ext.getAttribute('cx'),
            ecy = +ext.getAttribute('cy');
          const cox = +chOff.getAttribute('x'),
            coy = +chOff.getAttribute('y');
          const ccx = +chExt.getAttribute('cx'),
            ccy = +chExt.getAttribute('cy');
          const gsx = ccx ? ecx / ccx : 1,
            gsy = ccy ? ecy / ccy : 1;
          const gtx = ox - cox * gsx,
            gty = oy - coy * gsy;
          // Compose this group outward: X' = X*gs + gt.
          sx *= gsx;
          sy *= gsy;
          tx = tx * gsx + gtx;
          ty = ty * gsy + gty;
        }
      }
      cursor = parent;
    }
    return { sx, sy, tx, ty };
  }

  // Write one shape's absolute (record %) geometry into its OWN <a:xfrm>,
  // inverting the ancestor-group affine so grouped/drilled children land in
  // the right place.
  function writeShapeAbsoluteGeometry(shape) {
    if (!shape.srcNode) return;
    const g = ensureXfrm(shape.srcNode, shape);
    if (!g) return;
    const emu = state.pptxSlideSizeEmu;
    const absX = (shape.left / 100) * emu.cx,
      absY = (shape.top / 100) * emu.cy;
    const absW = (shape.width / 100) * emu.cx,
      absH = (shape.height / 100) * emu.cy;
    const a = ancestorAffineEmu(shape.srcNode);
    g.off.setAttribute('x', `${Math.round((absX - a.tx) / a.sx)}`);
    g.off.setAttribute('y', `${Math.round((absY - a.ty) / a.sy)}`);
    g.ext.setAttribute('cx', `${Math.round(absW / a.sx)}`);
    g.ext.setAttribute('cy', `${Math.round(absH / a.sy)}`);
  }

  // Push committed geometry into the slide XML. When the selection is exactly
  // one real PowerPoint group, remap the group's own <a:xfrm> (children follow
  // for free). Otherwise write each member's own xfrm through the inverse of
  // its ancestor-group affine — correct for drilled children, multi-selects,
  // and records-level groups alike.
  function commitGeometryToXml(members, origBB) {
    const sel = state.pptxSelection;
    if (!sel || members.length === 0) return;
    if (sel.groupNode && sel.ids.length === members.length) {
      const g = ensureXfrm(sel.groupNode, null);
      if (g) mapXfrmThroughBBox([g], origBB, selectionBBox(members));
      return;
    }
    members.forEach((s) => writeShapeAbsoluteGeometry(s));
  }

  const SPPR_FILL_TAGS = ['noFill', 'solidFill', 'gradFill', 'blipFill', 'pattFill', 'grpFill'];

  function writeSolidFill(spPr, hex) {
    const doc = slideDoc();
    if (!spPr || !doc) return;
    SPPR_FILL_TAGS.forEach((t) => {
      const n = byLocal(spPr, t);
      if (n) spPr.removeChild(n);
    });
    const fill = doc.createElementNS(A_NS, 'a:solidFill');
    const clr = doc.createElementNS(A_NS, 'a:srgbClr');
    clr.setAttribute('val', hex.replace('#', '').toUpperCase());
    fill.appendChild(clr);
    const ln = byLocal(spPr, 'ln');
    spPr.insertBefore(fill, ln || null); // fill precedes ln in the schema
  }

  function writeStroke(spPr, hex, widthPx) {
    const doc = slideDoc();
    if (!spPr || !doc) return;
    let ln = byLocal(spPr, 'ln');
    if (!ln) {
      ln = doc.createElementNS(A_NS, 'a:ln');
      const effect = byLocal(spPr, 'effectLst');
      spPr.insertBefore(ln, effect || null);
    }
    if (widthPx != null) ln.setAttribute('w', `${Math.max(0, Math.round(widthPx * 9525))}`);
    SPPR_FILL_TAGS.forEach((t) => {
      const n = byLocal(ln, t);
      if (n) ln.removeChild(n);
    });
    const fill = doc.createElementNS(A_NS, 'a:solidFill');
    const clr = doc.createElementNS(A_NS, 'a:srgbClr');
    clr.setAttribute('val', hex.replace('#', '').toUpperCase());
    fill.appendChild(clr);
    ln.insertBefore(fill, ln.firstChild);
  }

  /* ---- property edits --------------------------------------------------- */

  function setSelectionFill(hex) {
    selectionMembers().forEach((s) => {
      if (!FILL_KINDS[s.kind]) return;
      s.fillColor = hex;
      s.fillGradientCss = null;
      if (s.srcNode) writeSolidFill(byLocal(s.srcNode, 'spPr'), hex);
    });
    render.renderActiveSlideOnCanvas();
  }

  function setSelectionStroke(hex, widthPx) {
    selectionMembers().forEach((s) => {
      if (!STROKE_KINDS[s.kind]) return;
      s.strokeColor = hex;
      if (widthPx != null) s.strokeWidthPx = widthPx;
      if (s.srcNode)
        writeStroke(
          byLocal(s.srcNode, 'spPr'),
          hex,
          widthPx != null ? widthPx : s.strokeWidthPx || 1,
        );
    });
    render.renderActiveSlideOnCanvas();
  }

  function deleteSelection() {
    const sel = state.pptxSelection;
    const slide = currentSlide();
    if (!sel || !slide) return;
    if (sel.groupNode && sel.groupNode.parentNode) {
      sel.groupNode.parentNode.removeChild(sel.groupNode);
    } else {
      selectionMembers().forEach((s) => {
        if (s.srcNode && s.srcNode.parentNode) s.srcNode.parentNode.removeChild(s.srcNode);
      });
    }
    slide.shapes = slide.shapes.filter((s) => !sel.ids.includes(s.id));
    state.pptxSelection = null;
    render.renderActiveSlideOnCanvas();
    app.createToast && app.createToast('Shape removed from slide.', 'info');
  }

  // Full text of a shape, one line per paragraph (runs concatenated).
  function shapeFullText(shape) {
    return shape.paragraphs.map((p) => p.map((r) => r.text).join('')).join('\n');
  }

  // Does this shape hold real, user-visible text? Decorative custGeom art
  // often carries a throwaway/whitespace txBody — those are not text boxes.
  function shapeHasVisibleText(shape) {
    if (!shape.paragraphs || !shape.paragraphs.some((p) => p.some((r) => r.nodeRef))) return false;
    return shapeFullText(shape).replace(/[\s\u200B]/g, '').length > 0;
  }

  // Write edited text back into a text box. The sidebar exposes one field per
  // box (PowerPoint's unit), so the value is split by line and distributed
  // one line per paragraph; each paragraph's text lands in its first editable
  // run (the rest are cleared), which is exactly right for the split-run
  // sentences Google Slides exports and lossless for single-run paragraphs.
  function setShapeText(shape, value) {
    const lines = value.split('\n');
    const container = document.getElementById('slide-content-layer');
    const div = container ? container.querySelector(`[data-bsp-id="${shape.id}"]`) : null;
    const lastP = shape.paragraphs.length - 1;

    shape.paragraphs.forEach((pRuns, pIdx) => {
      const line =
        pIdx < lastP ? (lines[pIdx] != null ? lines[pIdx] : '') : lines.slice(pIdx).join('\n');
      let firstIdx = pRuns.findIndex((r) => r.nodeRef);
      if (firstIdx === -1) firstIdx = 0;
      pRuns.forEach((run, rIdx) => {
        const next = rIdx === firstIdx ? line : '';
        if (run.text === next) return;
        run.text = next;
        if (run.nodeRef) run.nodeRef.textContent = next;
        if (div) {
          const span = div.querySelector(`span[data-p="${pIdx}"][data-r="${rIdx}"]`);
          if (span) span.textContent = next;
        }
      });
    });
  }

  function nudgeSelection(dxPct, dyPct) {
    const members = selectionMembers();
    if (members.length === 0) return;
    const origBB = selectionBBox(members);
    members.forEach((s) => {
      s.left += dxPct;
      s.top += dyPct;
    });
    commitGeometryToXml(members, origBB);
    render.renderActiveSlideOnCanvas();
  }

  /* ---- drag / resize ---------------------------------------------------- */

  function beginModifierDrag(e) {
    const members = selectionMembers();
    if (members.length === 0) return;
    startPointerOp(e, members, (dxPct, dyPct, orig) => {
      members.forEach((s) => {
        const o = orig[s.id];
        s.left = o.left + dxPct;
        s.top = o.top + dyPct;
      });
    });
  }

  function beginModifierResize(e, handle) {
    const members = selectionMembers();
    if (members.length === 0) return;
    const bb = selectionBBox(members);
    startPointerOp(e, members, (dxPct, dyPct, orig) => {
      let nx = bb.x,
        ny = bb.y,
        nw = bb.w,
        nh = bb.h;
      if (handle.includes('r')) nw = Math.max(0.3, bb.w + dxPct);
      if (handle.includes('l')) {
        nx = Math.min(bb.x + dxPct, bb.x + bb.w - 0.3);
        nw = bb.w - (nx - bb.x);
      }
      if (handle.includes('b')) nh = Math.max(0.3, bb.h + dyPct);
      if (handle.includes('t')) {
        ny = Math.min(bb.y + dyPct, bb.y + bb.h - 0.3);
        nh = bb.h - (ny - bb.y);
      }
      const kx = nw / bb.w,
        ky = nh / bb.h;
      members.forEach((s) => {
        const o = orig[s.id];
        s.left = nx + (o.left - bb.x) * kx;
        s.top = ny + (o.top - bb.y) * ky;
        s.width = o.width * kx;
        s.height = o.height * ky;
      });
    });
  }

  // Shared pointer loop: applies `apply(dx%, dy%, origGeom)` on move (live
  // div updates only), then commits XML + full re-render on release.
  function startPointerOp(e, members, apply) {
    const startX = e.clientX,
      startY = e.clientY;
    const origBB = selectionBBox(members);
    const orig = {};
    members.forEach((s) => {
      orig[s.id] = { left: s.left, top: s.top, width: s.width, height: s.height };
    });
    const container = document.getElementById('slide-content-layer');
    let moved = false;

    const onMove = (mv) => {
      const dxPct = ((mv.clientX - startX) / state.scale / boardWpx()) * 100;
      const dyPct = ((mv.clientY - startY) / state.scale / boardHpx()) * 100;
      if (!moved && Math.abs(mv.clientX - startX) + Math.abs(mv.clientY - startY) < 3) return;
      moved = true;
      apply(dxPct, dyPct, orig);
      members.forEach((s) => {
        const div = container ? container.querySelector(`[data-bsp-id="${s.id}"]`) : null;
        if (div) {
          div.style.left = `${s.left}%`;
          div.style.top = `${s.top}%`;
          div.style.width = `${s.width}%`;
          div.style.height = `${s.height}%`;
        }
      });
      if (hudWrapper) {
        const bb = selectionBBox(members);
        hudWrapper.style.left = `${bb.x}%`;
        hudWrapper.style.top = `${bb.y}%`;
        hudWrapper.style.width = `${bb.w}%`;
        hudWrapper.style.height = `${bb.h}%`;
      }
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      if (!moved) return;
      commitGeometryToXml(members, origBB);
      render.renderActiveSlideOnCanvas();
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  }

  /* ---- renderer hooks --------------------------------------------------- */

  function attachModifierShapeInteractions(div, shape) {
    div.dataset.bspId = shape.id;
    if (!shape.editable) return;
    div.style.cursor = 'move';

    // A single-shape selection outlines the shape itself; a group
    // selection is marked only by the one group HUD box (PowerPoint-style),
    // so children stay un-outlined to avoid a mess of nested rectangles.
    const sel = state.pptxSelection;
    if (sel && !sel.groupId && sel.ids.includes(shape.id)) div.classList.add('bsp-mod-selected');

    div.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return;
      installGlobalHandlers();
      // Shift-click extends the selection (add/remove this shape's unit).
      if (e.shiftKey) {
        e.preventDefault();
        e.stopPropagation();
        toggleSelectShape(shape);
        return;
      }
      const sel = state.pptxSelection;
      const isSelected = sel && sel.ids.includes(shape.id);
      // Clicking inside an already-selected text box (on the text, not the
      // box chrome) drops through to caret editing instead of dragging.
      if (isSelected && shape.kind === 'text' && e.target !== div) return;
      e.preventDefault();
      e.stopPropagation();
      if (!isSelected) selectModifierShape(shape);
      beginModifierDrag(e);
    });

    div.addEventListener('contextmenu', (e) => {
      installGlobalHandlers();
      const sel = state.pptxSelection;
      if (!sel || !sel.ids.includes(shape.id)) selectModifierShape(shape);
      showModifierContextMenu(e, shape);
    });

    // Double-click drills into a group to select this individual child.
    if (shape.groupId) {
      div.addEventListener('dblclick', (e) => {
        e.preventDefault();
        e.stopPropagation();
        selectModifierShape(shape, true);
      });
    }
  }

  function attachModifierSelectionHUD() {
    const board = document.getElementById('slide-canvas');
    if (!board) return;
    board.querySelectorAll('.bsp-mod-hud').forEach((n) => n.remove());
    hudWrapper = null;
    if (state.activeKind() !== 'pptx' || !state.pptxSelection) return;
    if (state.nodeEditShapeId) return; // point-edit mode shows node dots, not the box HUD
    const members = selectionMembers();
    if (members.length === 0) {
      state.pptxSelection = null;
      return;
    }
    installGlobalHandlers();

    const bb = selectionBBox(members);
    const wrap = document.createElement('div');
    wrap.className = 'bsp-mod-hud transform-border';
    wrap.style.left = `${bb.x}%`;
    wrap.style.top = `${bb.y}%`;
    wrap.style.width = `${bb.w}%`;
    wrap.style.height = `${bb.h}%`;
    wrap.style.pointerEvents = 'none';

    const handles = [
      { name: 'tl', style: 'top:-6px;left:-6px;cursor:nwse-resize;' },
      { name: 'tr', style: 'top:-6px;right:-6px;cursor:nesw-resize;' },
      { name: 'bl', style: 'bottom:-6px;left:-6px;cursor:nesw-resize;' },
      { name: 'br', style: 'bottom:-6px;right:-6px;cursor:nwse-resize;' },
      { name: 't', style: 'top:-6px;left:50%;transform:translateX(-50%);cursor:ns-resize;' },
      { name: 'b', style: 'bottom:-6px;left:50%;transform:translateX(-50%);cursor:ns-resize;' },
      { name: 'l', style: 'top:50%;left:-6px;transform:translateY(-50%);cursor:ew-resize;' },
      { name: 'r', style: 'top:50%;right:-6px;transform:translateY(-50%);cursor:ew-resize;' },
    ];
    handles.forEach((h) => {
      const hd = document.createElement('div');
      hd.className = 'transform-handle';
      hd.style = h.style;
      hd.style.pointerEvents = 'auto';
      hd.addEventListener('mousedown', (e) => {
        e.stopPropagation();
        e.preventDefault();
        beginModifierResize(e, h.name);
      });
      wrap.appendChild(hd);
    });

    wrap.appendChild(buildPropsToolbar(members, bb));
    board.appendChild(wrap);
    hudWrapper = wrap;
  }

  function buildPropsToolbar(members, bb) {
    const bar = document.createElement('div');
    bar.className = 'bsp-mod-toolbar';
    if (bb.y < 9) {
      bar.style.bottom = '-46px';
    } else {
      bar.style.top = '-46px';
    }
    bar.addEventListener('mousedown', (e) => e.stopPropagation());

    const canFill = members.some((s) => FILL_KINDS[s.kind]);
    const canStroke = members.some((s) => STROKE_KINDS[s.kind]);
    const textMembers = members.filter(
      (s) =>
        s.kind === 'text' &&
        s.paragraphs &&
        s.paragraphs.some((p) => p.some((r) => r.nodeRef && (r.text || '').trim())),
    );
    const first =
      members.find((s) => FILL_KINDS[s.kind] && /^#[0-9a-f]{6}$/i.test(s.fillColor || '')) || {};
    const firstStroke =
      members.find((s) => STROKE_KINDS[s.kind] && /^#[0-9a-f]{6}$/i.test(s.strokeColor || '')) ||
      {};

    const sel = state.pptxSelection;
    if (sel && (sel.groupId || sel.ids.length > 1)) {
      const lbl = document.createElement('span');
      lbl.className = 'bsp-mod-toolbar-label';
      lbl.textContent = sel.groupId ? `Group · ${members.length}` : `${members.length} selected`;
      bar.appendChild(lbl);
    }

    // A color chip: a glyph identifying what it affects (A / fill / border)
    // over a bar showing the CURRENT color, with the native picker overlaid.
    const CHIP_GLYPH = {
      text: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M5 7V5h14v2M12 5v14M9 19h6"/></svg>',
      fill: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M12 3l7 7-6.5 6.5a2 2 0 0 1-2.8 0L4 11z"/><path d="M4 11h13"/></svg>',
      border:
        '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2"><rect x="4" y="4" width="16" height="16" rx="2"/></svg>',
    };
    const addChip = (title, kind, currentColor, onPick) => {
      const valid = /^#[0-9a-f]{6}$/i.test(currentColor || '');
      const wrap = document.createElement('label');
      wrap.className = 'bsp-mod-chip';
      wrap.title = title + (valid ? ` (${currentColor.toUpperCase()})` : '');
      const glyph = document.createElement('span');
      glyph.className = 'chip-glyph';
      glyph.innerHTML = CHIP_GLYPH[kind] || '';
      wrap.appendChild(glyph);
      const swatch = document.createElement('span');
      swatch.className = 'chip-swatch' + (valid ? '' : ' chip-swatch-none');
      if (valid) swatch.style.background = currentColor;
      wrap.appendChild(swatch);
      const input = document.createElement('input');
      input.type = 'color';
      input.value = valid ? currentColor : '#000000';
      input.addEventListener('input', (e) => {
        swatch.style.background = e.target.value;
        swatch.classList.remove('chip-swatch-none');
        onPick(e.target.value);
      });
      wrap.appendChild(input);
      bar.appendChild(wrap);
      return input;
    };

    if (textMembers.length) {
      const firstText =
        textMembers[0].paragraphs.flat().find((r) => /^#[0-9a-f]{6}$/i.test(r.color || '')) || {};
      addChip('Text color', 'text', firstText.color, (v) => setSelectionTextColor(v));
    }
    if (canFill) {
      addChip('Fill color', 'fill', first.fillColor, (v) => setSelectionFill(v));
    }
    if (canStroke) {
      addChip('Border color', 'border', firstStroke.strokeColor, (v) =>
        setSelectionStroke(v, null),
      );

      const width = document.createElement('input');
      width.type = 'number';
      width.min = '0';
      width.max = '40';
      width.step = '1';
      width.title = 'Border width (px)';
      width.value = `${firstStroke.strokeWidthPx || 0}`;
      width.addEventListener('change', (e) => {
        const w = Math.max(0, parseInt(e.target.value, 10) || 0);
        setSelectionStroke(firstStroke.strokeColor || '#000000', w);
      });
      bar.appendChild(width);
    }

    const iconBtn = (title, svg, action, danger) => {
      const b = document.createElement('button');
      b.title = title;
      if (danger) b.classList.add('danger');
      b.innerHTML = svg;
      b.addEventListener('click', action);
      bar.appendChild(b);
    };

    if (members.length === 1 && members[0].customGeometry && edit.enterNodeEditMode) {
      iconBtn(
        'Edit points (reshape)',
        '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20 20 4"/><rect x="2" y="18" width="4" height="4" rx="1" fill="currentColor" stroke="none"/><rect x="18" y="2" width="4" height="4" rx="1" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="2.2"/></svg>',
        () => edit.enterNodeEditMode(members[0]),
      );
    }
    if (members.length > 1 && !selectionHasGroup()) {
      iconBtn(
        'Group',
        '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="8" height="8" rx="1"/><rect x="13" y="13" width="8" height="8" rx="1"/></svg>',
        groupSelection,
      );
    }
    if (selectionHasGroup()) {
      iconBtn(
        'Ungroup (edit pieces)',
        '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1" stroke-dasharray="2 2"/></svg>',
        ungroupSelection,
      );
    }
    iconBtn(
      'Bring to front',
      '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><rect x="7" y="7" width="12" height="12" rx="1"/><path d="M5 15V5h10"/></svg>',
      () => reorderSelection(true),
    );
    iconBtn(
      'Send to back',
      '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><rect x="5" y="5" width="12" height="12" rx="1"/><path d="M19 9v10H9"/></svg>',
      () => reorderSelection(false),
    );
    iconBtn(
      'Delete',
      '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14"/></svg>',
      deleteSelection,
      true,
    );
    return bar;
  }

  /* ---- context menu ----------------------------------------------------- */

  const CTX_ID = 'bsp-mod-context-menu';

  function hideModifierContextMenu() {
    const m = document.getElementById(CTX_ID);
    if (m) m.remove();
    document.removeEventListener('mousedown', onCtxOutside, true);
  }
  function onCtxOutside(e) {
    const m = document.getElementById(CTX_ID);
    if (m && !m.contains(e.target)) hideModifierContextMenu();
  }

  function showModifierContextMenu(e, shape) {
    e.preventDefault();
    e.stopPropagation();
    hideModifierContextMenu();

    const items = [];
    if (selectionHasGroup()) items.push({ label: 'Ungroup', action: ungroupSelection });
    if (selectionMembers().length > 1 && !selectionHasGroup())
      items.push({ label: 'Group', action: groupSelection });
    if (shape.groupId)
      items.push({ label: 'Edit this piece', action: () => selectModifierShape(shape, true) });
    if (shape.customGeometry && edit.enterNodeEditMode)
      items.push({ label: 'Edit Points (reshape)', action: () => edit.enterNodeEditMode(shape) });
    items.push({ divider: true });
    items.push({ label: 'Bring to Front', action: () => reorderSelection(true) });
    items.push({ label: 'Send to Back', action: () => reorderSelection(false) });
    items.push({ divider: true });
    items.push({ label: 'Delete', action: deleteSelection, danger: true });

    const menu = document.createElement('div');
    menu.id = CTX_ID;
    menu.className = 'se-menu';
    items.forEach((item) => {
      if (item.divider) {
        const hr = document.createElement('div');
        hr.className = 'se-menu-sep';
        menu.appendChild(hr);
        return;
      }
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'se-menu-item' + (item.danger ? ' is-danger' : '');
      b.textContent = item.label;
      b.addEventListener('click', () => {
        hideModifierContextMenu();
        item.action();
      });
      menu.appendChild(b);
    });
    document.body.appendChild(menu);
    const rect = menu.getBoundingClientRect();
    let x = e.clientX,
      y = e.clientY;
    if (x + rect.width + 6 > window.innerWidth) x = window.innerWidth - rect.width - 6;
    if (y + rect.height + 6 > window.innerHeight) y = window.innerHeight - rect.height - 6;
    menu.style.left = `${Math.max(6, x)}px`;
    menu.style.top = `${Math.max(6, y)}px`;
    setTimeout(() => document.addEventListener('mousedown', onCtxOutside, true), 0);
  }

  /* ---- global handlers (marquee / deselect / keyboard), installed once --- */

  function beginMarquee(e) {
    // An empty-canvas click leaves point-edit mode instead of marqueeing.
    if (state.nodeEditShapeId) {
      edit.exitNodeEditMode && edit.exitNodeEditMode();
      return;
    }
    const container = document.getElementById('slide-content-layer');
    const board = document.getElementById('slide-canvas');
    if (!container || !board) return;
    const startX = e.clientX,
      startY = e.clientY;
    const boardRect = board.getBoundingClientRect();
    const box = document.createElement('div');
    box.className = 'bsp-mod-marquee';
    container.appendChild(box);
    let dragged = false;

    const toPct = (cx, cy) => ({
      x: ((cx - boardRect.left) / boardRect.width) * 100,
      y: ((cy - boardRect.top) / boardRect.height) * 100,
    });
    const onMove = (mv) => {
      if (!dragged && Math.abs(mv.clientX - startX) + Math.abs(mv.clientY - startY) < 4) return;
      dragged = true;
      const a = toPct(startX, startY),
        b = toPct(mv.clientX, mv.clientY);
      const x = Math.min(a.x, b.x),
        y = Math.min(a.y, b.y),
        w = Math.abs(a.x - b.x),
        h = Math.abs(a.y - b.y);
      box.style.left = `${x}%`;
      box.style.top = `${y}%`;
      box.style.width = `${w}%`;
      box.style.height = `${h}%`;
      box.__rect = { x, y, w, h };
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      box.remove();
      if (!dragged || !box.__rect) {
        clearModifierSelection();
        return;
      }
      const R = box.__rect;
      const slide = currentSlide();
      if (!slide) return;
      // Select every editable top-level unit that intersects the marquee.
      const hitUnits = new Set();
      const ids = [];
      slide.shapes.forEach((s) => {
        if (!s.editable) return;
        const ix =
          s.left < R.x + R.w &&
          s.left + s.width > R.x &&
          s.top < R.y + R.h &&
          s.top + s.height > R.y;
        if (!ix) return;
        const key = s.groupId || s.id;
        if (hitUnits.has(key)) return;
        hitUnits.add(key);
        unitIdsFor(s).forEach((id) => ids.push(id));
      });
      selectByIds(ids);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  }

  function installGlobalHandlers() {
    if (installed) return;
    installed = true;

    const board = document.getElementById('slide-canvas');
    const container = document.getElementById('slide-content-layer');
    if (board) {
      board.addEventListener('mousedown', (e) => {
        if (state.activeKind() !== 'pptx' || e.button !== 0) return;
        if (e.target === board || e.target === container) beginMarquee(e);
      });
    }

    document.addEventListener('keydown', (e) => {
      if (state.activeKind() !== 'pptx') return;
      const t = e.target;
      if (
        t &&
        (t.isContentEditable ||
          t.tagName === 'INPUT' ||
          t.tagName === 'TEXTAREA' ||
          t.tagName === 'SELECT')
      )
        return;
      const mod = e.metaKey || e.ctrlKey;
      if (mod && (e.key === 'g' || e.key === 'G')) {
        e.preventDefault();
        if (e.shiftKey) ungroupSelection();
        else groupSelection();
        return;
      }
      if (!state.pptxSelection) return;
      const step = e.shiftKey ? 1 : 0.2;
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        nudgeSelection(-step, 0);
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        nudgeSelection(step, 0);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        nudgeSelection(0, -step);
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        nudgeSelection(0, step);
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault();
        deleteSelection();
      } else if (e.key === 'Escape') {
        clearModifierSelection();
      }
    });
  }

  /* ---- styles ----------------------------------------------------------- */

  (function injectStyles() {
    const css = `
            .bsp-mod-selected { outline: 1.5px solid #f97316 !important; outline-offset: 0; }
            .bsp-mod-hud { border: 1.5px solid #f97316; pointer-events: none; }
            .bsp-mod-toolbar {
                position: absolute; left: 0; display: flex; align-items: center; gap: 6px;
                background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px;
                box-shadow: 0 6px 20px rgba(15, 23, 42, .12); padding: 5px 8px;
                pointer-events: auto; z-index: 60; white-space: nowrap;
            }
            .bsp-mod-chip {
                position: relative; width: 30px; height: 26px; display: inline-flex;
                flex-direction: column; align-items: center; justify-content: center; gap: 2px;
                border: 1px solid #e2e8f0; border-radius: 6px; cursor: pointer; overflow: hidden; background: #fff;
            }
            .bsp-mod-chip .chip-glyph { display: flex; color: #334155; line-height: 1; pointer-events: none; }
            .bsp-mod-chip .chip-swatch {
                width: 18px; height: 5px; border-radius: 2px; border: 1px solid rgba(15,23,42,.18);
                background: #ffffff; pointer-events: none;
            }
            /* No single color (mixed / gradient): a diagonal red slash. */
            .bsp-mod-chip .chip-swatch-none {
                background: linear-gradient(135deg, #fff 43%, #ef4444 43%, #ef4444 57%, #fff 57%);
            }
            .bsp-mod-chip input[type="color"] {
                position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0;
                border: none; padding: 0; margin: 0; cursor: pointer;
            }
            .bsp-mod-toolbar input[type="number"] {
                width: 42px; height: 24px; border: 1px solid #e2e8f0; border-radius: 6px;
                font-size: 11px; padding: 0 4px; color: #0f172a; background: #fff;
            }
            .bsp-mod-toolbar button {
                width: 24px; height: 24px; display: flex; align-items: center; justify-content: center;
                border: 1px solid #e2e8f0; border-radius: 6px; background: #fff; color: #334155; cursor: pointer;
            }
            .bsp-mod-toolbar button:hover { background: #f1f5f9; }
            .bsp-mod-toolbar button.danger { color: #dc2626; }
            .bsp-mod-toolbar button.danger:hover { background: #fef2f2; }
            .bsp-mod-toolbar-label { font-size: 10px; color: #64748b; font-weight: 600; padding-right: 2px; }
            .bsp-mod-marquee {
                position: absolute; border: 1px solid #f97316; background: rgba(249,115,22,.10);
                pointer-events: none; z-index: 55; left: 0; top: 0; width: 0; height: 0;
            }
        `;
    const tag = document.createElement('style');
    tag.textContent = css;
    document.head.appendChild(tag);
  })();

  Object.assign(edit, {
    selectModifierShape,
    clearModifierSelection,
    toggleSelectShape,
    selectByIds,
    groupSelection,
    ungroupSelection,
    reorderSelection,
    setSelectionFill,
    setSelectionStroke,
    setSelectionTextColor,
    deleteSelection,
    showModifierContextMenu,
    attachModifierShapeInteractions,
    attachModifierSelectionHUD,
    shapeFullText,
    shapeHasVisibleText,
    setShapeText,
  });
})((window.BSPSlideEditor = window.BSPSlideEditor || {}));

/* End src/renderer/panel/features/slide-editor/edit/modifier-shapes.js */


/* Begin src/renderer/panel/features/slide-editor/edit/node-edit.js */

/* =========================================================================
   BSPSlideEditor — freeform node (point) editing for imported vector shapes
   -------------------------------------------------------------------------
   Lets the user reshape a custom-geometry (Freeform) shape by dragging the
   control points of its path. Every <a:pt> in the shape's <a:custGeom> becomes
   a draggable handle — anchor points (segment endpoints) are solid, Bézier
   control points are hollow. Dragging rewrites the pt's x/y directly in the
   slide XML (so export round-trips) and repaints the shape's SVG live.

   Coordinate spaces: a pt lives in its <a:path> w/h space; the path fills the
   shape box. So normalized (x/w, y/h) maps to a percentage inside the shape,
   which maps to a board percentage — with flipH/flipV mirrored. Rotation is
   not inverted (rare for hand-reshaped art); such shapes still edit, just with
   handles following the un-rotated box.

   Depends on state, render (renderActiveSlideOnCanvas), app (toasts), core
   (parseCustomGeometry / customGeometryPathD). Renderer calls
   renderNodeEditHandles() after the modifier pass.
   ========================================================================= */
(function (BSPSlideEditor) {
    "use strict";

    const edit = BSPSlideEditor.edit = BSPSlideEditor.edit || {};
    const state = BSPSlideEditor.state;
    const render = BSPSlideEditor.render = BSPSlideEditor.render || {};
    const app = BSPSlideEditor.app = BSPSlideEditor.app || {};

    const boardWpx = () => 1280;
    const boardHpx = () => {
        const e = state.pptxSlideSizeEmu;
        return (e && e.cx > 0 && e.cy > 0) ? Math.round(1280 * (e.cy / e.cx)) : 720;
    };

    const currentSlide = () => state.slides[state.activeSlideIndex] || null;
    const shapeById = (id) => { const s = currentSlide(); return s ? s.shapes.find((x) => x.id === id) : null; };
    const custGeomOf = (shape) => (shape && shape.srcNode) ? shape.srcNode.getElementsByTagNameNS("*", "custGeom")[0] : null;

    // Collect every <a:pt> of the shape's custGeom with the path space it lives
    // in and whether it is an on-curve anchor (vs a Bézier control point).
    function buildModel(shape) {
        const cg = custGeomOf(shape);
        if (!cg) return null;
        const pathNodes = cg.getElementsByTagNameNS("*", "path");
        const pts = [];
        for (let pi = 0; pi < pathNodes.length; pi++) {
            const pn = pathNodes[pi];
            let w = parseFloat(pn.getAttribute("w") || "0") || 0;
            let h = parseFloat(pn.getAttribute("h") || "0") || 0;
            if (w <= 0 || h <= 0) {
                let mx = 1, my = 1;
                const all = pn.getElementsByTagNameNS("*", "pt");
                for (let k = 0; k < all.length; k++) {
                    mx = Math.max(mx, parseFloat(all[k].getAttribute("x") || "0") || 0);
                    my = Math.max(my, parseFloat(all[k].getAttribute("y") || "0") || 0);
                }
                if (w <= 0) w = mx;
                if (h <= 0) h = my;
            }
            for (let c = 0; c < pn.childNodes.length; c++) {
                const cmd = pn.childNodes[c];
                if (!cmd || cmd.nodeType !== 1) continue;
                const ptEls = [];
                for (let n = 0; n < cmd.childNodes.length; n++) {
                    const ch = cmd.childNodes[n];
                    if (ch.nodeType === 1 && ch.localName === "pt") ptEls.push(ch);
                }
                ptEls.forEach((ptEl, idx) => {
                    let anchor = true;
                    if (cmd.localName === "cubicBezTo") anchor = (idx === 2);
                    else if (cmd.localName === "quadBezTo") anchor = (idx === 1);
                    pts.push({ ptEl, w, h, anchor });
                });
            }
        }
        return pts.length ? { shapeId: shape.id, pts } : null;
    }

    function enterNodeEditMode(shape) {
        if (!shape || !shape.customGeometry || !shape.srcNode) {
            app.createToast && app.createToast("Only Freeform vector shapes have editable points.", "info");
            return;
        }
        const model = buildModel(shape);
        if (!model) { app.createToast && app.createToast("No editable points found on this shape.", "info"); return; }
        state.nodeEditModel = model;
        state.nodeEditShapeId = shape.id;
        installEscHandler();
        render.renderActiveSlideOnCanvas();
        app.createToast && app.createToast("Editing points — drag the dots to reshape. Press Esc when done.", "info");
    }

    function exitNodeEditMode() {
        if (!state.nodeEditShapeId) return;
        state.nodeEditShapeId = null;
        state.nodeEditModel = null;
        render.renderActiveSlideOnCanvas();
    }

    function ptToCanvasPct(shape, pt) {
        let nx = pt.w ? (parseFloat(pt.ptEl.getAttribute("x") || "0") || 0) / pt.w : 0;
        let ny = pt.h ? (parseFloat(pt.ptEl.getAttribute("y") || "0") || 0) / pt.h : 0;
        if (shape.flipH) nx = 1 - nx;
        if (shape.flipV) ny = 1 - ny;
        return { x: shape.left + nx * shape.width, y: shape.top + ny * shape.height };
    }

    // Re-parse the shape's custGeom and repaint its SVG (or clip-path) in place,
    // without a full slide re-render, so dragging stays smooth.
    function refreshLive(shape) {
        const cg = custGeomOf(shape);
        shape.customGeometry = BSPSlideEditor.core.parseCustomGeometry(cg);
        const div = document.querySelector(`[data-bsp-id="${shape.id}"]`);
        if (!div || !shape.customGeometry) return;
        const wPx = (shape.width / 100) * boardWpx();
        const hPx = (shape.height / 100) * boardHpx();
        const paths = shape.customGeometry.paths || [];
        const svg = div.querySelector("svg");
        if (svg) {
            const els = svg.querySelectorAll("path");
            els.forEach((el, i) => { if (paths[i]) el.setAttribute("d", BSPSlideEditor.core.customGeometryPathD(paths[i], wPx, hPx)); });
        } else {
            const clipD = paths.filter((p) => p.fill !== "none").map((p) => BSPSlideEditor.core.customGeometryPathD(p, wPx, hPx)).join(" ");
            if (clipD) div.style.clipPath = `path('${clipD}')`;
        }
    }

    function startNodeDrag(e, shape, pt, dot) {
        if (e.button !== 0) return;
        e.preventDefault();
        e.stopPropagation();
        const startX = e.clientX, startY = e.clientY;
        const origX = parseFloat(pt.ptEl.getAttribute("x") || "0") || 0;
        const origY = parseFloat(pt.ptEl.getAttribute("y") || "0") || 0;

        const onMove = (mv) => {
            const dxPct = ((mv.clientX - startX) / state.scale / boardWpx()) * 100;
            const dyPct = ((mv.clientY - startY) / state.scale / boardHpx()) * 100;
            let dnx = shape.width ? dxPct / shape.width : 0;
            let dny = shape.height ? dyPct / shape.height : 0;
            if (shape.flipH) dnx = -dnx;
            if (shape.flipV) dny = -dny;
            pt.ptEl.setAttribute("x", `${Math.round(origX + dnx * pt.w)}`);
            pt.ptEl.setAttribute("y", `${Math.round(origY + dny * pt.h)}`);
            refreshLive(shape);
            const pos = ptToCanvasPct(shape, pt);
            dot.style.left = `${pos.x}%`;
            dot.style.top = `${pos.y}%`;
        };
        const onUp = () => {
            document.removeEventListener("mousemove", onMove);
            document.removeEventListener("mouseup", onUp);
            render.renderActiveSlideOnCanvas(); // full sync (thumbnail, handles)
        };
        document.addEventListener("mousemove", onMove);
        document.addEventListener("mouseup", onUp);
    }

    function renderNodeEditHandles() {
        const board = document.getElementById("slide-canvas");
        if (!board) return;
        board.querySelectorAll(".bsp-node-layer").forEach((n) => n.remove());
        if (state.activeKind() !== "pptx" || !state.nodeEditShapeId) return;
        const shape = shapeById(state.nodeEditShapeId);
        const model = state.nodeEditModel;
        if (!shape || !model) { state.nodeEditShapeId = null; return; }

        const layer = document.createElement("div");
        layer.className = "bsp-node-layer";
        layer.style.position = "absolute";
        layer.style.inset = "0";
        layer.style.pointerEvents = "none";
        layer.style.zIndex = "70";

        model.pts.forEach((pt) => {
            const pos = ptToCanvasPct(shape, pt);
            const dot = document.createElement("div");
            dot.className = "bsp-node-dot" + (pt.anchor ? " anchor" : " ctrl");
            dot.style.left = `${pos.x}%`;
            dot.style.top = `${pos.y}%`;
            dot.style.pointerEvents = "auto";
            dot.addEventListener("mousedown", (e) => startNodeDrag(e, shape, pt, dot));
            layer.appendChild(dot);
        });

        // A small "Done" chip so the mode is obviously exitable by mouse too.
        const done = document.createElement("button");
        done.className = "bsp-node-done";
        done.textContent = "Done editing points";
        done.style.left = `${Math.max(0, shape.left)}%`;
        done.style.top = `${Math.max(0, shape.top)}%`;
        done.addEventListener("mousedown", (e) => e.stopPropagation());
        done.addEventListener("click", exitNodeEditMode);
        layer.appendChild(done);

        board.appendChild(layer);
    }

    let escInstalled = false;
    function installEscHandler() {
        if (escInstalled) return;
        escInstalled = true;
        document.addEventListener("keydown", (e) => {
            if (state.nodeEditShapeId && e.key === "Escape") { e.preventDefault(); exitNodeEditMode(); }
        });
    }

    (function injectStyles() {
        const css = `
            .bsp-node-dot {
                position: absolute; width: 11px; height: 11px; margin: -6px 0 0 -6px;
                border-radius: 50%; background: #f97316; border: 2px solid #fff;
                box-shadow: 0 1px 3px rgba(0,0,0,.35); cursor: grab; z-index: 71;
            }
            .bsp-node-dot.ctrl { width: 9px; height: 9px; margin: -5px 0 0 -5px;
                border-radius: 2px; background: #fff; border: 2px solid #f97316; }
            .bsp-node-dot:active { cursor: grabbing; }
            .bsp-node-dot:hover { background: #ea580c; }
            .bsp-node-dot.ctrl:hover { background: #ffedd5; }
            .bsp-node-done {
                position: absolute; transform: translateY(-140%); pointer-events: auto;
                background: #f97316; color: #fff; border: none; border-radius: 7px;
                font-size: 11px; font-weight: 600; padding: 4px 9px; cursor: pointer;
                box-shadow: 0 4px 14px rgba(249,115,22,.4); white-space: nowrap; z-index: 72;
            }
            .bsp-node-done:hover { background: #ea580c; }
        `;
        const tag = document.createElement("style");
        tag.textContent = css;
        document.head.appendChild(tag);
    })();

    Object.assign(edit, {
        enterNodeEditMode,
        exitNodeEditMode,
        renderNodeEditHandles,
        isNodeEditing: () => !!state.nodeEditShapeId,
    });
})(window.BSPSlideEditor = window.BSPSlideEditor || {});

/* End src/renderer/panel/features/slide-editor/edit/node-edit.js */


/* Begin src/renderer/panel/features/slide-editor/edit/builder.js */

/* =========================================================================
   BSPSlideEditor — builder selection, inspector & content operations
   -------------------------------------------------------------------------
   Builder-mode editing surface: element selection + drag, the style inspector
   sync (typography/shape-fill/radius/pen panels), inline text editing, element
   property mutation (text/position/style toggles), slide background, and
   add/duplicate/delete operations for elements and slides.

   Depends on edit/geometry.js (normalizeCircleGeometry), edit/tools.js
   (switchActiveTool), render and app. State in BSPSlideEditor.state.
   ========================================================================= */
(function (BSPSlideEditor) {
    "use strict";

    const edit = BSPSlideEditor.edit = BSPSlideEditor.edit || {};
    const state = BSPSlideEditor.state;
    const render = BSPSlideEditor.render = BSPSlideEditor.render || {};
    const app = BSPSlideEditor.app = BSPSlideEditor.app || {};

    function selectBuilderElement(e, id) {
        e.stopPropagation();
        state.selectedElementId = id;

        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === id);
        if (!el) return;

        render.renderActiveSlideOnCanvas();

        const startX = e.clientX;
        const startY = e.clientY;
        const origX = el.x;
        const origY = el.y;

        function onMouseMove(moveEv) {
            const dx = moveEv.clientX - startX;
            const dy = moveEv.clientY - startY;

            const scaleAdjustedDx = dx / state.scale;
            const scaleAdjustedDy = dy / state.scale;

            const dxPercent = (scaleAdjustedDx / 1280) * 100;
            const dyPercent = (scaleAdjustedDy / 720) * 100;

            const proposedX = Math.min(Math.max(origX + dxPercent, 0), 100 - el.w);
            const proposedY = Math.min(Math.max(origY + dyPercent, 0), 100 - el.h);

            // Smart-guide / grid snapping (no-op if both disabled).
            const snapped = edit.snapDragPosition(el, proposedX, proposedY);
            el.x = snapped.x;
            el.y = snapped.y;
            edit.drawSnapGuides(snapped.guides);

            render.renderActiveSlideOnCanvas();
        }

        function onMouseUp() {
            document.removeEventListener("mousemove", onMouseMove);
            document.removeEventListener("mouseup", onMouseUp);
            edit.clearSnapGuides();
            syncBuilderStyleInspector();
        }

        document.addEventListener("mousemove", onMouseMove);
        document.addEventListener("mouseup", onMouseUp);
    }

    // Synchronize elements properties to inspector input forms
    function syncBuilderStyleInspector() {
        const controls = document.getElementById("builder-style-controls");
        const emptyState = document.getElementById("builder-style-empty-state");
        const lblSelected = document.getElementById("lbl-selected-element");

        document.getElementById("pen-stroke-controls").classList.add("hidden");
        document.getElementById("border-radius-controls").classList.add("hidden");
        document.getElementById("typography-controls").classList.remove("hidden");
        document.getElementById("shape-fill-controls").classList.add("hidden");
        document.getElementById("layout-dimensions-inspector-block").classList.remove("hidden");
        document.getElementById("text-content-inspector-block").classList.remove("hidden");

        if (state.activeTool === "pencil") {
            controls.classList.add("is-live");
            emptyState.classList.add("hidden");
            lblSelected.textContent = "Pencil Active";

            document.getElementById("pen-stroke-controls").classList.remove("hidden");
            document.getElementById("inp-pen-stroke-width").value = state.penWidth;
            document.getElementById("inp-pen-stroke-color").value = state.penColor;
            document.getElementById("lbl-pen-stroke-hex").textContent = state.penColor;
            document.getElementById("typography-controls").classList.add("hidden");
            document.getElementById("layout-dimensions-inspector-block").classList.add("hidden");
            document.getElementById("text-content-inspector-block").classList.add("hidden");
            return;
        }

        if (!state.selectedElementId) {
            controls.classList.remove("is-live");
            emptyState.classList.remove("hidden");
            lblSelected.textContent = "None Selected";
            return;
        }

        controls.classList.add("is-live");
        emptyState.classList.add("hidden");

        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === state.selectedElementId);
        if (!el) return;

        lblSelected.textContent = el.id.substring(0, 16);

        document.getElementById("inp-element-text").value = el.text || "";
        document.getElementById("inp-element-x").value = el.x;
        document.getElementById("inp-element-y").value = el.y;
        document.getElementById("inp-element-w").value = el.w;
        document.getElementById("inp-element-h").value = el.h;

        if (el.type === "text") {
            document.getElementById("inp-element-font").value = el.fontFace || "Arial";
            document.getElementById("inp-element-size").value = el.fontSize || 16;
            const weightSel = document.getElementById("inp-element-weight");
            if (weightSel) weightSel.value = String(el.fontWeight != null ? el.fontWeight : (el.bold ? 700 : 400));
            document.getElementById("inp-element-color").value = el.fontColor || "#ffffff";
            document.getElementById("lbl-font-color-hex").textContent = el.fontColor || "#ffffff";

            styleToggleBtn("btn-toggle-bold", el.bold);
            styleToggleBtn("btn-toggle-italic", el.italic);
            styleToggleBtn("btn-toggle-underline", el.underline);

            ["left", "center", "right"].forEach((align) => {
                const btn = document.getElementById(`btn-align-${align}`);
                if (btn) btn.classList.toggle("is-active", el.align === align);
            });

            document.getElementById("inp-element-text").disabled = false;
        } else if (el.type === "shape") {
            document.getElementById("shape-fill-controls").classList.remove("hidden");
            document.getElementById("lbl-shape-fill-title").textContent = "Shape Fill Color";
            document.getElementById("inp-shape-fill").value = el.fillColor || "#22d3ee";
            document.getElementById("lbl-shape-fill-hex").textContent = el.fillColor || "#22d3ee";
            const shOpPct = Math.round((el.fillOpacity != null ? el.fillOpacity : 1) * 100);
            const shOp = document.getElementById("inp-fill-opacity");
            if (shOp) shOp.value = shOpPct;
            const shOpLbl = document.getElementById("lbl-fill-opacity");
            if (shOpLbl) shOpLbl.textContent = `${shOpPct}%`;
            document.getElementById("inp-element-text").disabled = true;
            document.getElementById("text-content-inspector-block").classList.add("hidden");
            document.getElementById("typography-controls").classList.add("hidden");

            document.getElementById("border-radius-controls").classList.remove("hidden");
            const rtl = el.rtl !== undefined ? el.rtl : 8;
            const rtr = el.rtr !== undefined ? el.rtr : 8;
            const rbr = el.rbr !== undefined ? el.rbr : 8;
            const rbl = el.rbl !== undefined ? el.rbl : 8;

            document.getElementById("inp-radius-tl").value = rtl;
            document.getElementById("inp-radius-tr").value = rtr;
            document.getElementById("inp-radius-br").value = rbr;
            document.getElementById("inp-radius-bl").value = rbl;

            if (state.isRadiusLocked) {
                document.getElementById("inp-radius-all").value = rtl;
                document.getElementById("lbl-radius-all").textContent = `${rtl}px`;
            }
        } else if (el.type === "image") {
            document.getElementById("inp-element-text").disabled = true;
            document.getElementById("text-content-inspector-block").classList.add("hidden");
            document.getElementById("typography-controls").classList.add("hidden");

            document.getElementById("border-radius-controls").classList.remove("hidden");
            const rtl = el.rtl !== undefined ? el.rtl : 8;
            const rtr = el.rtr !== undefined ? el.rtr : 8;
            const rbr = el.rbr !== undefined ? el.rbr : 8;
            const rbl = el.rbl !== undefined ? el.rbl : 8;

            document.getElementById("inp-radius-tl").value = rtl;
            document.getElementById("inp-radius-tr").value = rtr;
            document.getElementById("inp-radius-br").value = rbr;
            document.getElementById("inp-radius-bl").value = rbl;

            if (state.isRadiusLocked) {
                document.getElementById("inp-radius-all").value = rtl;
                document.getElementById("lbl-radius-all").textContent = `${rtl}px`;
            }
        } else if (el.type === "pencil" || el.type === "bezier") {
            document.getElementById("inp-element-text").disabled = true;
            document.getElementById("text-content-inspector-block").classList.add("hidden");
            document.getElementById("typography-controls").classList.add("hidden");

            // Stroke (with enable/remove toggle)
            document.getElementById("pen-stroke-controls").classList.remove("hidden");
            document.getElementById("inp-pen-stroke-width").value = el.strokeWidth || 4;
            document.getElementById("inp-pen-stroke-color").value = el.strokeColor || "#22d3ee";
            document.getElementById("lbl-pen-stroke-hex").textContent = el.strokeColor || "#22d3ee";
            const strokeChk = document.getElementById("inp-stroke-enabled");
            if (strokeChk) strokeChk.checked = el.strokeEnabled !== false;

            // Fill (enable + color + opacity) — works for both pencil and bezier
            document.getElementById("closed-loop-fill-options").classList.remove("hidden");
            document.getElementById("inp-pencil-is-filled").checked = !!el.isLoopFilled;
            if (el.isLoopFilled) {
                document.getElementById("shape-fill-controls").classList.remove("hidden");
                document.getElementById("lbl-shape-fill-title").textContent = "Fill Color";
                document.getElementById("inp-shape-fill").value = el.fillColor || "#22d3ee";
                document.getElementById("lbl-shape-fill-hex").textContent = el.fillColor || "#22d3ee";
                const opPct = Math.round((el.fillOpacity != null ? el.fillOpacity : 1) * 100);
                const op = document.getElementById("inp-fill-opacity");
                if (op) op.value = opPct;
                const opLbl = document.getElementById("lbl-fill-opacity");
                if (opLbl) opLbl.textContent = `${opPct}%`;
            }
        }
    }

    function styleToggleBtn(id, isActive) {
        const btn = document.getElementById(id);
        if (btn) btn.classList.toggle("is-active", !!isActive);
    }

    function enterTextEditMode(id) {
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide?.elements.find((item) => item.id === id);
        if (!el || el.type !== "text") return;

        state.editingTextElementId = id;
        state.selectedElementId = id;
        state.activeTool = "select";
        render.renderActiveSlideOnCanvas();

        requestAnimationFrame(() => {
            const textLayer = document.querySelector(`#${CSS.escape(id)} [contenteditable="true"]`);
            if (!textLayer) return;
            textLayer.focus();
            const range = document.createRange();
            range.selectNodeContents(textLayer);
            range.collapse(false);
            const selection = window.getSelection();
            selection.removeAllRanges();
            selection.addRange(range);
        });
    }

    // Sync a text element's stored height (%) to its rendered content height,
    // so auto-height text boxes grow/shrink with their content.
    function autoSizeTextElement(div, el) {
        if (!div || !el) return;
        const px = div.offsetHeight || 0;
        if (px > 0) {
            el.h = Math.max(2, Math.round((px / 720) * 10000) / 100);
        }
    }

    function updateCanvasTextElement(id, value) {
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide?.elements.find((item) => item.id === id);
        if (!el || el.type !== "text") return;

        el.text = value;
        if (state.selectedElementId === id) {
            const inspectorText = document.getElementById("inp-element-text");
            if (inspectorText) inspectorText.value = value;
        }

        // Live-grow the box (and its selection outline) as lines are added/removed.
        if (el.autoHeight !== false) {
            const div = document.getElementById(id);
            if (div) {
                autoSizeTextElement(div, el);
                const hud = document.querySelector(".transform-border");
                if (hud) hud.style.height = `${el.h}%`;
            }
        }

        render.updateLiveThumbnail(state.activeSlideIndex);
        if (app.recordHistory) app.recordHistory();
    }

    function updateActiveElementText(val) {
        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === state.selectedElementId);
        if (el && el.type === "text") {
            el.text = val;
            const div = document.getElementById(state.selectedElementId);
            if (div) {
                div.querySelector("div").textContent = val;
            }
            if (app.recordHistory) app.recordHistory();
        }
    }

    function updateActiveElementPosition() {
        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === state.selectedElementId);
        if (!el) return;

        el.x = parseInt(document.getElementById("inp-element-x").value) || 0;
        el.y = parseInt(document.getElementById("inp-element-y").value) || 0;
        el.w = parseInt(document.getElementById("inp-element-w").value) || 10;
        el.h = parseInt(document.getElementById("inp-element-h").value) || 10;
        edit.normalizeCircleGeometry(el, "width");

        const div = document.getElementById(state.selectedElementId);
        if (div) {
            div.style.left = `${el.x}%`;
            div.style.top = `${el.y}%`;
            div.style.width = `${el.w}%`;
            div.style.height = `${el.h}%`;
        }
        if (app.recordHistory) app.recordHistory();
    }

    function updateActiveElementStyle(property, value) {
        if (state.activeTool === "pencil") {
            if (property === "strokeColor") {
                state.penColor = value;
                document.getElementById("lbl-pen-stroke-hex").textContent = value;
            } else if (property === "strokeWidth") {
                state.penWidth = value;
            }
            return;
        }

        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === state.selectedElementId);
        if (!el) return;

        el[property] = value;

        // Remember the latest text font/color so new text boxes inherit them.
        if (el.type === "text" && (property === "fontFace" || property === "fontColor")) {
            if (!state.lastTextStyle) state.lastTextStyle = {};
            state.lastTextStyle[property] = value;
        }

        if (property === "fontColor") {
            document.getElementById("lbl-font-color-hex").textContent = value;
        } else if (property === "fillColor") {
            document.getElementById("lbl-shape-fill-hex").textContent = value;
        } else if (property === "strokeColor") {
            document.getElementById("lbl-pen-stroke-hex").textContent = value;
        }

        render.renderActiveSlideOnCanvas();
    }

    function toggleActiveElementStyle(styleName) {
        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        const el = currentSlide.elements.find((item) => item.id === state.selectedElementId);
        if (!el) return;

        el[styleName] = !el[styleName];
        render.renderActiveSlideOnCanvas();
    }

    function updateSlideBackground(hexColor) {
        const currentSlide = state.slides[state.activeSlideIndex];
        if (!currentSlide) return;

        currentSlide.background = hexColor;
        currentSlide.transparentBg = false; // choosing a color turns transparency off

        const board = document.getElementById("slide-canvas");
        board.style.backgroundImage = "none"; // clear any transparency checkerboard
        board.style.backgroundColor = hexColor;
        document.getElementById("inp-slide-bg").value = hexColor;
        document.getElementById("inp-slide-bg-hex").value = hexColor;
        const chk = document.getElementById("chk-slide-transparent");
        if (chk) chk.checked = false;

        render.updateLiveThumbnail(state.activeSlideIndex);
        if (app.recordHistory) app.recordHistory();
    }

    function toggleSlideTransparent(isTransparent) {
        const currentSlide = state.slides[state.activeSlideIndex];
        if (!currentSlide) return;

        currentSlide.transparentBg = !!isTransparent;
        render.renderActiveSlideOnCanvas();
        render.updateLiveThumbnail(state.activeSlideIndex);
        app.createToast(isTransparent ? "Slide background set to transparent" : "Slide background restored", "info");
    }

    function addTextToActiveSlide() {
        const currentSlide = state.slides[state.activeSlideIndex];
        if (!currentSlide) return;

        const newId = `text_${Date.now()}`;
        const last = state.lastTextStyle || {};
        currentSlide.elements.push({
            id: newId,
            type: "text",
            text: "Add text",
            x: 25, y: 42, w: 50, h: 7,
            fontSize: 30,
            fontColor: last.fontColor || "#000000",
            fontFace: last.fontFace || "Poppins",
            bold: false, align: "center",
            autoHeight: true,
        });

        state.selectedElementId = newId;
        edit.switchActiveTool("select");
        render.renderActiveSlideOnCanvas();
        app.createToast("New text block added to slide frame", "success");
    }

    function addShapeToActiveSlide(shapeType) {
        const currentSlide = state.slides[state.activeSlideIndex];
        if (!currentSlide) return;

        const newId = `shape_${Date.now()}`;
        const geometry = shapeType === "CIRCLE"
            ? { x: 40.625, y: 33.333, w: 18.75, h: 33.333 }
            : { x: 35, y: 30, w: 30, h: 30 };
        currentSlide.elements.push({
            id: newId,
            type: "shape",
            shapeType: shapeType,
            fillColor: shapeType === "CIRCLE" ? "#14b8a6" : "#22d3ee",
            ...geometry,
            rtl: 8, rtr: 8, rbr: 8, rbl: 8,
        });

        state.selectedElementId = newId;
        edit.switchActiveTool("select");
        render.renderActiveSlideOnCanvas();
        app.createToast(`Added new ${shapeType.toLowerCase()} shape layer`, "success");
    }

    function promptAddImage() {
        // No default URL: the panel runs offline, so a remote placeholder
        // would only ever resolve to a broken image.
        const imgUrl = prompt("Enter an image URL or data URI:", "");
        if (!imgUrl) return;
        addImageToActiveSlide(imgUrl);
    }

    function triggerImageUpload() {
        const input = document.getElementById("image-file-input");
        if (!input) return;
        input.value = "";
        input.click();
    }

    function handleImageUpload(event) {
        const file = event.target.files?.[0];
        if (!file) return;

        if (!file.type.startsWith("image/")) {
            app.createToast("Choose a valid image file.", "error");
            return;
        }

        const reader = new FileReader();
        reader.addEventListener('load', () => {
            addImageToActiveSlide(reader.result, file.name);
        });
        reader.readAsDataURL(file);
        reader.addEventListener('error', () => app.createToast("Could not read the image file.", "error"));
    }

    function addImageToActiveSlide(imgUrl, label = "Image") {
        const currentSlide = state.slides[state.activeSlideIndex];
        if (!currentSlide) return;

        const newId = `image_${Date.now()}`;
        currentSlide.elements.push({
            id: newId,
            type: "image",
            url: imgUrl,
            label,
            x: 20, y: 15, w: 60, h: 60,
            rtl: 8, rtr: 8, rbr: 8, rbl: 8,
        });

        state.selectedElementId = newId;
        edit.switchActiveTool("select");
        render.renderActiveSlideOnCanvas();
        app.createToast("Image frame integrated successfully", "success");
    }

    function addNewSlide() {
        const newId = state.slides.length + 1;
        // Match the default starter slide: white background + one "Add text" box.
        const defaultSlide = typeof window.BSPCreateDefaultNativeSlideModel === "function"
            ? window.BSPCreateDefaultNativeSlideModel(newId)
            : {
            id: newId,
            kind: "native",
            background: "#FFFFFF",
            transparentBg: false,
            elements: [
                {
                    id: `el_${Date.now()}_text`,
                    type: "text",
                    text: "Add text",
                    x: 20, y: 42, w: 60, h: 8,
                    fontSize: 30, fontColor: "#000000", fontFace: "Arial", bold: false, align: "center",
                    autoHeight: true,
                },
            ],
        };
        state.slides.push(defaultSlide);

        state.activeSlideIndex = state.slides.length - 1;
        state.selectedElementId = null;
        render.renderSlideDeckNavigator();
        render.renderActiveSlideOnCanvas();
        app.createToast("Appended new slide frame to document", "success");
    }

    function duplicateActiveSlide() {
        const currentSlide = state.slides[state.activeSlideIndex];
        if (!currentSlide) return;

        const clonedElements = currentSlide.elements.map((el) => ({ ...el, id: `${el.id}_cloned_${Date.now()}` }));

        state.slides.splice(state.activeSlideIndex + 1, 0, {
            id: state.slides.length + 1,
            kind: "native",
            background: currentSlide.background,
            transparentBg: !!currentSlide.transparentBg,
            elements: clonedElements,
        });

        state.activeSlideIndex += 1;
        state.selectedElementId = null;
        render.renderSlideDeckNavigator();
        render.renderActiveSlideOnCanvas();
        app.createToast("Slide cloned successfully", "success");
    }

    function deleteActiveSlide() {
        deleteSlideAt(state.activeSlideIndex);
    }

    function deleteSlideAt(idx) {
        if (state.slides.length <= 1) {
            app.createToast("Presentations require at least 1 slide layer.", "error");
            return;
        }

        state.slides.splice(idx, 1);
        state.activeSlideIndex = Math.max(0, idx - 1);
        state.selectedElementId = null;

        render.renderSlideDeckNavigator();
        render.renderActiveSlideOnCanvas();
        app.createToast("Removed slide from deck", "info");
    }

    function deleteActiveElement() {
        if (!state.selectedElementId) return;
        const currentSlide = state.slides[state.activeSlideIndex];
        currentSlide.elements = currentSlide.elements.filter((el) => el.id !== state.selectedElementId);
        state.selectedElementId = null;
        render.renderActiveSlideOnCanvas();
        app.createToast("Deleted layer element", "info");
    }

    Object.assign(edit, {
        selectBuilderElement,
        syncBuilderStyleInspector,
        styleToggleBtn,
        enterTextEditMode,
        autoSizeTextElement,
        updateCanvasTextElement,
        updateActiveElementText,
        updateActiveElementPosition,
        updateActiveElementStyle,
        toggleActiveElementStyle,
        updateSlideBackground,
        toggleSlideTransparent,
        addTextToActiveSlide,
        addShapeToActiveSlide,
        promptAddImage,
        triggerImageUpload,
        handleImageUpload,
        addImageToActiveSlide,
        addNewSlide,
        duplicateActiveSlide,
        deleteActiveSlide,
        deleteSlideAt,
        deleteActiveElement,
    });
})(window.BSPSlideEditor = window.BSPSlideEditor || {});

/* End src/renderer/panel/features/slide-editor/edit/builder.js */


/* Begin src/renderer/panel/features/slide-editor/edit/context-menu.js */

/* =========================================================================
   BSPSlideEditor — element right-click menu & z-ordering (Builder mode)
   -------------------------------------------------------------------------
   PowerPoint-style stacking order. Builder elements render in array order, so
   later in the array == drawn on top:
     - Bring to Front  -> move to end
     - Bring Forward   -> swap with next
     - Send Backward   -> swap with previous
     - Send to Back    -> move to start

   showElementContextMenu() selects the element and pops a floating menu at the
   cursor (built in-DOM, no markup needed). Depends on state, render, app, and
   edit (deleteActiveElement). Builder mode only.
   ========================================================================= */
(function (BSPSlideEditor) {
    "use strict";

    const edit = BSPSlideEditor.edit = BSPSlideEditor.edit || {};
    const state = BSPSlideEditor.state;
    const render = BSPSlideEditor.render = BSPSlideEditor.render || {};
    const app = BSPSlideEditor.app = BSPSlideEditor.app || {};

    const MENU_ID = "bsp-element-context-menu";

    function activeBuilderSlide() {
        if (state.activeKind() !== "native") return null;
        return state.slides[state.activeSlideIndex] || null;
    }

    function selectedIndex(slide) {
        if (!slide || !state.selectedElementId) return -1;
        return slide.elements.findIndex((el) => el.id === state.selectedElementId);
    }

    function afterReorder(label) {
        render.renderActiveSlideOnCanvas();
        render.updateLiveThumbnail(state.activeSlideIndex);
        app.createToast(label, "info");
    }

    function bringToFront() {
        const slide = activeBuilderSlide();
        const i = selectedIndex(slide);
        if (i < 0 || i === slide.elements.length - 1) return;
        const [el] = slide.elements.splice(i, 1);
        slide.elements.push(el);
        afterReorder("Brought to front");
    }

    function sendToBack() {
        const slide = activeBuilderSlide();
        const i = selectedIndex(slide);
        if (i <= 0) return;
        const [el] = slide.elements.splice(i, 1);
        slide.elements.unshift(el);
        afterReorder("Sent to back");
    }

    function bringForward() {
        const slide = activeBuilderSlide();
        const i = selectedIndex(slide);
        if (i < 0 || i === slide.elements.length - 1) return;
        [slide.elements[i], slide.elements[i + 1]] = [slide.elements[i + 1], slide.elements[i]];
        afterReorder("Brought forward");
    }

    function sendBackward() {
        const slide = activeBuilderSlide();
        const i = selectedIndex(slide);
        if (i <= 0) return;
        [slide.elements[i], slide.elements[i - 1]] = [slide.elements[i - 1], slide.elements[i]];
        afterReorder("Sent backward");
    }

    function hideElementContextMenu() {
        const existing = document.getElementById(MENU_ID);
        if (existing) existing.remove();
        document.removeEventListener("mousedown", onOutsideMouseDown, true);
        document.removeEventListener("keydown", onMenuKeyDown, true);
        window.removeEventListener("blur", hideElementContextMenu);
    }

    function onOutsideMouseDown(e) {
        const menu = document.getElementById(MENU_ID);
        if (menu && !menu.contains(e.target)) hideElementContextMenu();
    }

    function onMenuKeyDown(e) {
        if (e.key === "Escape") hideElementContextMenu();
    }

    function showElementContextMenu(e, id) {
        if (state.activeKind() !== "native") return;
        e.preventDefault();
        e.stopPropagation();
        hideElementContextMenu();

        // Make sure the right-clicked element is the selected one.
        state.selectedElementId = id;
        render.renderActiveSlideOnCanvas();

        const items = [
            { label: "Bring to Front", action: bringToFront },
            { label: "Bring Forward", action: bringForward },
            { label: "Send Backward", action: sendBackward },
            { label: "Send to Back", action: sendToBack },
            { divider: true },
            { label: "Delete", action: () => edit.deleteActiveElement(), danger: true },
        ];

        const menu = document.createElement("div");
        menu.id = MENU_ID;
        menu.className = "se-menu";
        menu.style.left = "0px";
        menu.style.top = "0px";

        items.forEach((item) => {
            if (item.divider) {
                const hr = document.createElement("div");
                hr.className = "se-menu-sep";
                menu.appendChild(hr);
                return;
            }
            const btn = document.createElement("button");
            btn.type = "button";
            btn.className = "se-menu-item" + (item.danger ? " is-danger" : "");
            btn.textContent = item.label;
            btn.addEventListener("click", () => {
                hideElementContextMenu();
                item.action();
            });
            menu.appendChild(btn);
        });

        document.body.appendChild(menu);

        // Position at cursor, clamped to the viewport.
        const rect = menu.getBoundingClientRect();
        const pad = 6;
        let x = e.clientX;
        let y = e.clientY;
        if (x + rect.width + pad > window.innerWidth) x = window.innerWidth - rect.width - pad;
        if (y + rect.height + pad > window.innerHeight) y = window.innerHeight - rect.height - pad;
        menu.style.left = `${Math.max(pad, x)}px`;
        menu.style.top = `${Math.max(pad, y)}px`;

        // Defer outside-click binding so this same event doesn't immediately close it.
        setTimeout(() => {
            document.addEventListener("mousedown", onOutsideMouseDown, true);
            document.addEventListener("keydown", onMenuKeyDown, true);
            window.addEventListener("blur", hideElementContextMenu);
        }, 0);
    }

    Object.assign(edit, {
        bringToFront,
        bringForward,
        sendBackward,
        sendToBack,
        showElementContextMenu,
        hideElementContextMenu,
    });
})(window.BSPSlideEditor = window.BSPSlideEditor || {});

